### Component Code (`discover-button.tsx`):
```tsx
"use client";

import { useState } from "react";
import { motion } from "motion/react";

import {
  Search01Icon,
  FavouriteIcon,
  Fire02Icon,
  MultiplicationSignIcon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";

// Change Here
const TABS = [
  {
    id: "popular",
    label: "Popular",
    icon: Fire02Icon,
    color: "text-red-500",
    fill: "fill-red-500",
    bg: "bg-red-50",
  },
  {
    id: "favorites",
    label: "Favorites",
    icon: FavouriteIcon,
    color: "text-gray-900",
    fill: "fill-gray-900",
    bg: "bg-gray-100",
  },
] as const;

export default function DiscoverButton() {
  const [activeTab, setActiveTab] = useState<(typeof TABS)[number]["id"]>(
    TABS[0].id
  );
  const [isSearchExpanded, setIsSearchExpanded] = useState(false);

  return (
    <div className=" flex  flex-col md:flex-row items-center gap-3 p-2 h-full ">
      {/* Search Button / Input */}
      <motion.div
        layout
        transition={{
          type: "spring",
          damping: 20,
          stiffness: 230,
          mass: 1.2,
        }}
        onClick={() => !isSearchExpanded && setIsSearchExpanded(true)}
        className={`flex items-center bg-white rounded-[3rem] shadow-lg cursor-pointer h-[60px] overflow-hidden relative px-[1.125rem]  py-2   ${
          isSearchExpanded ? "flex-1" : ""
        }`}
      >
        <div className="shrink-0">
          <HugeiconsIcon
            icon={Search01Icon}
            className="w-6 h-6 text-gray-800"
          />
        </div>

        <motion.div
          initial={false}
          animate={{
            width: isSearchExpanded ? "auto" : "0px",
            opacity: isSearchExpanded ? 1 : 0,
            filter: isSearchExpanded ? "blur(0px)" : "blur(4px)",
            marginLeft: isSearchExpanded ? "12px" : "0px",
          }}
          transition={{
            type: "spring",
            damping: 20,
            stiffness: 230,
            mass: 1.2,
          }}
          className="overflow-hidden -mb-0.5 flex items-center"
        >
          <input
            type="text"
            placeholder="Search"
            className="border-0 outline-none bg-transparent text-lg focus-visible:ring-0 focus-visible:ring-offset-0 w-full"
            onClick={(e) => e.stopPropagation()}
          />
        </motion.div>
      </motion.div>

      {/* Tab Container / Close Button */}
      <motion.div
        layout
        transition={{
          type: "spring",
          damping: 20,
          stiffness: 230,
          mass: 1.2,
        }}
        className={`flex  items-center bg-white rounded-[20px] md:rounded-[3rem] shadow-lg ${isSearchExpanded ? `h-[60px]` : `h-[120px]` } md:h-[60px] overflow-hidden relative`}
      >
        {/* Wrapper to control clipping - clips from right side */}
        <motion.div
          initial={false}
          animate={{
            width: isSearchExpanded ? "60px" : "auto",
          }}
          transition={{
            type: "spring",
            damping: 20,
            stiffness: 230,
            mass: 1.2,
          }}
          className="overflow-hidden relative h-full flex  items-center"
        >
          {/* Tabs Group - stays in place, gets clipped */}
          <motion.div
            initial={false}
            animate={{
              opacity: isSearchExpanded ? 0 : 1,
              filter: isSearchExpanded ? "blur(4px)" : "blur(0px)",
              width: "auto",
            }}
            transition={{
              duration: 0.2,
            }}
            className={` flex   items-center  whitespace-nowrap `}
          >
            <div className="flex flex-col md:flex-row items-center gap-2 px-2  md:px-[6px]">
              {TABS.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex  items-center gap-2 w-full  px-7 md:px-6 py-3 rounded-2xl  md:rounded-[3rem] transition-colors relative ${
                    activeTab === tab.id ? tab.color : "text-gray-700"
                  }`}
                >
                  {activeTab === tab.id && (
                    <motion.span
                      layoutId="bubble"
                      className={`absolute inset-0 z-0 ${tab.bg} rounded-[12px] md:rounded-[9999]`}
                      // style={{ borderRadius: 9999 }}
                      transition={{
                        type: "spring",
                        bounce: 0.19,
                        duration: 0.4,
                      }}
                    />
                  )}
                  <HugeiconsIcon
                    icon={tab.icon}
                    className={`w-5 h-5 relative z-10 ${
                      activeTab === tab.id ? tab.fill : ""
                    }`}
                  />
                  <span className="font-semibold font-mono uppercase relative z-10">
                    {tab.label}
                  </span>
                </button>
              ))}
            </div>
          </motion.div>

          {/* Close Button - positioned absolutely on top */}
          <motion.div
            initial={false}
            animate={{
              opacity: isSearchExpanded ? 1 : 0,
              filter: isSearchExpanded ? "blur(0px)" : "blur(4px)",
            }}
            transition={{
              duration: 0.2,
            }}
            className="absolute  inset-0 flex items-center justify-center"
            style={{ pointerEvents: isSearchExpanded ? "auto" : "none" }}
          >
            <button
              onClick={() => setIsSearchExpanded(false)}
              className="shrink-0 cursor-pointer"
            >
              <HugeiconsIcon
                icon={MultiplicationSignIcon}
                className="w-6 h-6 text-gray-800"
              />
            </button>
          </motion.div>
        </motion.div>
      </motion.div>
    </div>
  );
}

```

### Demo Usage (`demo.tsx`):
```tsx
"use client";
import Component from "@/components/auto-index/urvish-discover-button/discover-button";

export default function Demo() {
  return <div className="flex min-h-[320px] w-full items-center justify-center overflow-auto p-6"><Component /></div>;
}

```
### Dependencies:
```bash
motion @hugeicons/core-free-icons @hugeicons/react clsx tailwind-merge
```

### Reviewed component details
**Appearance**
A responsive control group (stacked vertically on mobile, horizontal on desktop) composed of two white, drop-shadowed pill containers. The first container features a dark search icon next to an expandable input field. The second container displays two monospace, uppercase text tabs with icons—Popular (red fire icon and red tinted background) and Favorites (dark gray icon and neutral tinted background)—which transforms into a compact container displaying a dark multiplication sign close button when active.

**Behavior**
Clicking the search container expands it across available space via spring motion while animating input width, opacity, and blur. Simultaneously, the adjacent container shrinks to a 60px width, blurring and fading out the tabs while revealing the close icon. Clicking the close button reverses this animation. Selecting between tabs smoothly slides an underlying background pill via layout animations.

**Controls**
Consists of an expandable search container trigger, a standard text input with "Search" placeholder, two clickable tab buttons ("Popular", "Favorites"), and an overlay close button.

**Accessibility**
Employs semantic HTML `<button>` and `<input>` elements, setting `pointer-events: none` on inactive overlay containers. However, it lacks WAI-ARIA tab semantics (`role="tablist"`, `role="tab"`, `aria-selected`), lacks `aria-expanded` and `aria-controls` on toggles, and provides no programmatic label or `aria-label` for the search input.

**Installation Needs**
Requires a React environment supporting `"use client"`, Tailwind CSS, `motion` (imported from `motion/react`), `@hugeicons/react`, and `@hugeicons/core-free-icons`.

